import React, { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { aiAdvisorAPI } from '../services/api';
import toast from 'react-hot-toast';

const AIAdvisor = () => {
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [chatHistory, setChatHistory] = useState([]);

  const askQuestionMutation = useMutation({
    mutationFn: aiAdvisorAPI.askQuestion,
    onSuccess: (data) => {
      setResponse(data);
      setChatHistory(prev => [...prev, {
        type: 'question',
        content: question,
        timestamp: new Date()
      }, {
        type: 'answer',
        content: data,
        timestamp: new Date()
      }]);
      setQuestion('');
    },
    onError: () => {
      toast.error('Failed to get AI response');
    },
    onSettled: () => {
      setIsLoading(false);
    }
  });

  const voiceCommandMutation = useMutation({
    mutationFn: aiAdvisorAPI.processVoiceCommand,
    onSuccess: (data) => {
      setResponse(data);
      setChatHistory(prev => [...prev, {
        type: 'voice',
        content: 'Voice command processed',
        timestamp: new Date()
      }, {
        type: 'answer',
        content: data,
        timestamp: new Date()
      }]);
    },
    onError: () => {
      toast.error('Failed to process voice command');
    }
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!question.trim()) return;

    setIsLoading(true);
    askQuestionMutation.mutate(question);
  };

  const handleVoiceCommand = () => {
    if (isRecording) {
      setIsRecording(false);
      return;
    }

    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      toast.error('Voice recognition not supported in this browser');
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();

    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => {
      setIsRecording(true);
      toast.success('Listening...');
    };

    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript;
      setQuestion(transcript);
      voiceCommandMutation.mutate(transcript);
    };

    recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      toast.error('Voice recognition failed');
      setIsRecording(false);
    };

    recognition.onend = () => {
      setIsRecording(false);
    };

    recognition.start();
  };

  const quickQuestions = [
    "What's the best breeding season for cattle?",
    "How do I improve my animals' genetics?",
    "What are the signs of a healthy breeding animal?",
    "How often should I breed my animals?",
    "What factors affect breeding success?",
    "How do I select the best breeding pairs?"
  ];

  const handleQuickQuestion = (quickQuestion) => {
    setQuestion(quickQuestion);
    setIsLoading(true);
    askQuestionMutation.mutate(quickQuestion);
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>
          <span className="emoji">🤖</span>
          AI Breeding Advisor
        </h1>
        <p>Get expert advice on animal breeding, genetics, and farm management.</p>
      </div>

      <div className="grid grid-2">
        <div className="card">
          <div className="card-header">
            <h3>
              <span className="emoji">💬</span>
              Ask Your Question
            </h3>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <input
                type="text"
                className="form-control"
                placeholder="Ask anything about animal breeding, genetics, or farm management..."
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                disabled={isLoading}
              />
            </div>
            <div className="d-flex gap-2">
              <button
                type="button"
                className={`btn ${isRecording ? 'btn-danger' : 'btn-secondary'}`}
                onClick={handleVoiceCommand}
                disabled={isLoading}
              >
                <span className="emoji">{isRecording ? '🎤' : '🎙️'}</span>
                {isRecording ? 'Stop' : 'Voice'}
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isLoading || !question.trim()}
              >
                {isLoading ? (
                  <div className="spinner"></div>
                ) : (
                  <>
                    <span className="emoji">📤</span>
                    Send
                  </>
                )}
              </button>
            </div>
          </form>

          {response && (
            <div className="mt-4 p-3" style={{background: 'var(--farm-cream)', borderRadius: 'var(--radius-md)'}}>
              <div className="d-flex align-center gap-2 mb-2">
                <span className="emoji">🤖</span>
                <strong>AI Advisor Response</strong>
              </div>
              <div>{response}</div>
            </div>
          )}

          {chatHistory.length > 0 && (
            <div className="mt-4">
              <h4>Conversation History</h4>
              <div className="chat-messages">
                {chatHistory.map((message, index) => (
                  <div key={index} className={`message ${message.type}`}>
                    <div className="message-content">
                      {message.content}
                    </div>
                    <div className="message-time">
                      {message.timestamp.toLocaleTimeString()}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="card">
          <div className="card-header">
            <h3>
              <span className="emoji">💡</span>
              Quick Questions
            </h3>
          </div>
          <div className="d-flex flex-column gap-2">
            {quickQuestions.map((quickQuestion, index) => (
              <button
                key={index}
                className="btn btn-outline btn-sm text-left"
                onClick={() => handleQuickQuestion(quickQuestion)}
                disabled={isLoading}
                style={{justifyContent: 'flex-start', textAlign: 'left'}}
              >
                <span className="emoji">❓</span>
                {quickQuestion}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-3 mt-4">
        <div className="card">
          <div className="card-header">
            <h3>
              <span className="emoji">📚</span>
              Breeding Tips
            </h3>
          </div>
          <div className="d-flex flex-column gap-3">
            <div>
              <h4>Optimal Breeding Age</h4>
              <p>Most farm animals reach breeding maturity at 12-18 months, depending on species and breed.</p>
            </div>
            <div>
              <h4>Genetic Diversity</h4>
              <p>Maintain genetic diversity by avoiding close relatives and introducing new bloodlines periodically.</p>
            </div>
            <div>
              <h4>Health Assessment</h4>
              <p>Always ensure animals are in excellent health before breeding to maximize success rates.</p>
            </div>
            <div>
              <h4>Record Keeping</h4>
              <p>Maintain detailed records of breeding history, genetics, and offspring performance.</p>
            </div>
          </div>
        </div>

        <div className="card">
          <div className="card-header">
            <h3>
              <span className="emoji">🤖</span>
              AI Capabilities
            </h3>
          </div>
          <div className="d-flex flex-column gap-3">
            <div className="d-flex align-center gap-2">
              <span className="emoji">🧬</span>
              <span>Genetic Analysis</span>
            </div>
            <div className="d-flex align-center gap-2">
              <span className="emoji">📊</span>
              <span>Breeding Recommendations</span>
            </div>
            <div className="d-flex align-center gap-2">
              <span className="emoji">🏥</span>
              <span>Health Assessment</span>
            </div>
            <div className="d-flex align-center gap-2">
              <span className="emoji">📅</span>
              <span>Breeding Scheduling</span>
            </div>
            <div className="d-flex align-center gap-2">
              <span className="emoji">🎯</span>
              <span>Performance Prediction</span>
            </div>
            <div className="d-flex align-center gap-2">
              <span className="emoji">💡</span>
              <span>Expert Advice</span>
            </div>
          </div>
        </div>

        <div className="card">
          <div className="card-header">
            <h3>
              <span className="emoji">🌟</span>
              Success Stories
            </h3>
          </div>
          <div className="d-flex flex-column gap-3">
            <div>
              <h4>🐄 Cattle Breeding</h4>
              <p>Increased milk production by 25% using AI-recommended breeding pairs.</p>
            </div>
            <div>
              <h4>🐑 Sheep Management</h4>
              <p>Improved wool quality through genetic analysis and selective breeding.</p>
            </div>
            <div>
              <h4>🐖 Pig Farming</h4>
              <p>Enhanced growth rates by 30% with optimized breeding schedules.</p>
            </div>
            <div>
              <h4>🐐 Goat Herding</h4>
              <p>Reduced disease susceptibility through careful genetic selection.</p>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default AIAdvisor;
